/**
 * Verify the Firebase-issued ID token and allow only the designated account.
 * Never trust UID/email supplied separately by the browser.
 */
export async function verifyFirebaseIdToken(
  idToken: unknown
): Promise<AuthenticatedUser | null> {
  if (typeof idToken !== 'string' || !idToken.trim()) {
    return null;
  }

  try {
    const firebaseApp = getApps().find((app) => app.name === '[DEFAULT]')
      ?? initializeApp({
        credential: applicationDefault(),
        projectId: 'silken-will-kthgf',
      });

    const decoded = await getAuth(firebaseApp).verifyIdToken(idToken.trim());

    if (
      decoded.uid !== ALLOWED_FIREBASE_UID ||
      typeof decoded.email !== 'string' ||
      decoded.email.trim().toLowerCase() !== ALLOWED_EMAIL
    ) {
      return null;
    }

    return {
      id: ALLOWED_FIREBASE_UID,
      email: ALLOWED_EMAIL,
      name: typeof decoded.name === 'string' && decoded.name.trim()
        ? decoded.name.trim()
        : 'NovaQuant Manager',
      photoUrl: typeof decoded.picture === 'string' ? decoded.picture : undefined,
      provider: typeof decoded.firebase?.sign_in_provider === 'string'
        ? decoded.firebase.sign_in_provider
        : 'firebase',
    };
  } catch (err) {
    console.warn('[FIREBASE TOKEN VERIFICATION FAILED]');
    return null;
  }
}

function base64UrlEncode(str: string): string {
  return Buffer.from(str)
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');
}

function base64UrlDecode(str: string): string {
  let base64 = str.replace(/-/g, '+').replace(/_/g, '/');
  while (base64.length % 4) {
    base64 += '=';
  }
  return Buffer.from(base64, 'base64').toString('utf8');
}

/**
 * Signs a standard JWT with HMAC-SHA256
 */
export function signJwt(payload: AuthenticatedUser, expiresInSeconds: number = 86400 * 7): string {
  const header = { alg: 'HS256', typ: 'JWT' };
  const exp = Math.floor(Date.now() / 1000) + expiresInSeconds;
  const body = { ...payload, exp };

  const encodedHeader = base64UrlEncode(JSON.stringify(header));
  const encodedBody = base64UrlEncode(JSON.stringify(body));
  const signature = crypto
    .createHmac('sha256', JWT_SECRET)
    .update(`${encodedHeader}.${encodedBody}`)
    .digest('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');

  return `${encodedHeader}.${encodedBody}.${signature}`;
}

/**
 * Verifies a JWT and extracts the user payload
 */
export function verifyJwt(token: string): AuthenticatedUser | null {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;

    const [encodedHeader, encodedBody, signature] = parts;
    const expectedSignature = crypto
      .createHmac('sha256', JWT_SECRET)
      .update(`${encodedHeader}.${encodedBody}`)
      .digest('base64')
      .replace(/=/g, '')
      .replace(/\+/g, '-')
      .replace(/\//g, '_');

    if (signature !== expectedSignature) {
      return null;
    }

    const payload = JSON.parse(base64UrlDecode(encodedBody));

    if (
      typeof payload.exp !== 'number' ||
      payload.exp <= Math.floor(Date.now() / 1000) ||
      payload.id !== ALLOWED_FIREBASE_UID ||
      typeof payload.email !== 'string' ||
      payload.email.trim().toLowerCase() !== ALLOWED_EMAIL
    ) {
      return null;
    }

    return {
      id: ALLOWED_FIREBASE_UID,
      email: ALLOWED_EMAIL,
      name: typeof payload.name === 'string' && payload.name.trim()
        ? payload.name.trim()
        : 'NovaQuant Manager',
      photoUrl: payload.photoUrl,
      provider: payload.provider,
    };
  } catch {
    return null;
  }
}

/**
 * Synchronizes or creates a user record in the PostgreSQL database
 */
export async function syncUserToDb(userToSync: AuthenticatedUser): Promise<void> {
  try {
    const { users } = await import('../src/db/schema.ts');
    const { db } = await import('../src/db/index.ts');
    const { eq } = await import('drizzle-orm');

    const existing = await db.select().from(users).where(eq(users.uid, userToSync.id)).limit(1);
    if (existing.length === 0) {
      await db.insert(users).values({
        uid: userToSync.id,
        email: userToSync.email,
        displayName: userToSync.name,
        photoUrl: userToSync.photoUrl || null,
      });
    } else {
      await db.update(users).set({
        email: userToSync.email,
        displayName: userToSync.name,
        photoUrl: userToSync.photoUrl || existing[0].photoUrl,
      }).where(eq(users.uid, userToSync.id));
    }
  } catch (err) {
    console.error('[AUTH SYNC ERROR]', err);
  }
}

// Extend Express Request type
export interface RequestWithUser extends Request {
  user?: AuthenticatedUser;
}

/**
 * Express Middleware: Authenticates user exclusively via a valid Bearer JWT.
 * Invalid or missing authentication fails closed with HTTP 401.
 */
export function authenticateUser(
  req: RequestWithUser,
  res: Response,
  next: NextFunction
): void {
  // Frontend/static assets must remain publicly reachable.
  // Only /api/* routes require authentication.
  if (!req.path.startsWith('/api/')) {
    return next();
  }

  // Public health endpoint: used by uptime and deployment checks.
  // Only this exact GET route is exempted.
  if (req.method === 'GET' && req.path === '/api/health') {
    return next();
  }

  // Public authentication/bootstrap endpoints.
  // These must be reachable before a JWT exists.
  const publicAuthRoutes = new Set([
    '/api/auth/login',
    '/api/auth/google',
    '/api/auth/register',
  ]);

  if (req.method === 'POST' && publicAuthRoutes.has(req.path)) {
    return next();
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      error: 'Authentication required',
      code: 'AUTH_REQUIRED',
    });
  }

  const token = authHeader.substring(7).trim();

  if (!token) {
    return res.status(401).json({
      error: 'Authentication token missing',
      code: 'AUTH_TOKEN_MISSING',
    });
  }

  const resolvedUser = verifyJwt(token);

  if (!resolvedUser) {
    return res.status(401).json({
      error: 'Authentication token invalid or expired',
      code: 'AUTH_TOKEN_INVALID',
    });
  }

  req.user = resolvedUser;

  syncUserToDb(resolvedUser).catch((err) => {
    console.error('[AUTH SYNC ERROR]', err);
  });

  next();
}
