app.post('/api/settings/risk', async (req: any, res: any) => {
  if (!requireSettingsAdmin(req, res)) return;

  const requestedMode = req.body?.tradingMode;

  // Only DEMO or LIVE are valid modes.
  if (
    requestedMode !== undefined &&
    requestedMode !== 'DEMO' &&
    requestedMode !== 'LIVE'
  ) {
    return res.status(400).json({
      error: 'Invalid tradingMode. Allowed values are DEMO or LIVE.',
    });
  }

  const userId = req.user?.id || DEFAULT_USER.id;

  // LIVE cannot be activated merely by changing risk settings.
  // It requires the separately verified exchange authorization flow.
  if (requestedMode === 'LIVE') {
    const targetExchange: SupportedExchange =
      userSelectedStrategyExchange[userId] || 'Binance';

    const conn = await getUserExchangeConnectionByExchangePersistent(
      userId,
      targetExchange
    );

    const capitalState = capitalManager.getCapitalState(
      userId,
      targetExchange
    );

    if (
      !conn ||
      conn.status !== 'CONNECTED' ||
      !conn.is_live_trading_enabled ||
      !capitalState.isLiveTradingEnabled
    ) {
      return res.status(403).json({
        error:
          'LIVE mode cannot be activated until verified exchange LIVE authorization and CapitalManager authorization are both active.',
        exchange: targetExchange,
        exchangeConnected: Boolean(
          conn && conn.status === 'CONNECTED'
        ),
        exchangeLiveTradingEnabled: Boolean(
          conn?.is_live_trading_enabled
        ),
        capitalLiveTradingEnabled: Boolean(
          capitalState.isLiveTradingEnabled
        ),
      });
    }
  }

  // Update risk settings.
  riskSettings = {
    ...riskSettings,
    ...(req.body?.settings || {}),
  };

  if (requestedMode !== undefined) {
    tradingMode = requestedMode;
    riskSettings.tradingMode = requestedMode;

    // Switching away from LIVE invalidates the previous LIVE session.
    if (requestedMode === 'DEMO') {
      liveStartVerified = false;
      sessionProfitTargetReached = false;
      sessionStartingBalance = 0;
    }
  }

  res.json({
    success: true,
    settings: riskSettings,
    tradingMode,
  });
});

