// ---------------------------------------------------------------------------------
// LIVE STARTUP POSITION SAFETY RECOVERY
// ---------------------------------------------------------------------------------
async function reconcileLivePositionsOnStartup(): Promise<void> {
  liveStartupRecoveryBlocked = false;

  if (tradingMode !== 'LIVE') {
    console.log('[LIVE STARTUP RECOVERY] Skipped: trading mode is not LIVE.');
    return;
  }

  try {
    const userId = DEFAULT_USER.id;
    const connection = await getUserExchangeConnectionByExchangePersistent(
      userId,
      'Binance'
    );

    if (!connection || connection.is_live_trading_enabled !== 1) {
      console.log(
        '[LIVE STARTUP RECOVERY] No LIVE-enabled Binance connection found.'
      );
      return;
    }

    const adapter = getAdapterForConnection(connection);

    if (!adapter.getPositions) {
      console.warn(
        '[LIVE STARTUP RECOVERY] Binance adapter does not expose getPositions().'
      );
      return;
    }

    const positions = await adapter.getPositions();

    if (!positions.length) {
      liveStartupRecoveryBlocked = false;
      console.log(
        '[LIVE STARTUP RECOVERY] Binance Futures has no open positions. ' +
        'LIVE autonomous scanner is allowed after the normal Start verification.'
      );
      return;
    }

    liveStartupRecoveryBlocked = true;

    console.warn(
      `[LIVE STARTUP RECOVERY] Detected ${positions.length} existing Binance Futures position(s). ` +
      'Local activeTrades is not persisted, so autonomous new entries will remain blocked.'
    );

    for (const position of positions) {
      console.warn(
        `[LIVE STARTUP RECOVERY] Existing position: ${position.symbol} ` +
        `${position.side} size=${position.size} entry=${position.entryPrice} ` +
        `mark=${position.markPrice} uPnL=${position.unrealizedPnl}.`
      );
    }

    // Fail closed: do not allow the autonomous scanner to open another
    // position while an exchange position exists without local trade metadata.
    activeTradingProcessesRunning = false;
    autonomousScannerRunning = false;
    if (autonomousScanTimer) {
      clearTimeout(autonomousScanTimer);
      autonomousScanTimer = null;
    }

    console.warn(
      '[LIVE STARTUP RECOVERY] FAIL-CLOSED: autonomous trading is blocked until ' +
      'the existing exchange position is reconciled.'
    );
  } catch (err: any) {
    liveStartupRecoveryBlocked = true;
    activeTradingProcessesRunning = false;
    autonomousScannerRunning = false;

    if (autonomousScanTimer) {
      clearTimeout(autonomousScanTimer);
      autonomousScanTimer = null;
    }

    console.error(
      '[LIVE STARTUP RECOVERY] Position check failed. ' +
      'Autonomous LIVE trading remains blocked:',
      err?.message || err
    );
  }
}

// ---------------------------------------------------------------------------------
// VITE MIDDLEWARE & SERVER STARTUP
// ---------------------------------------------------------------------------------
async function startServer() {
  // Initialize WebSocket Server on the HTTP Server instance
  wss = new WebSocketServer({ server, path: '/ws' });

  wss.on('connection', (ws: WebSocket, req) => {
    wsClients.add(ws);
    const clientIp = req.socket.remoteAddress || '127.0.0.1';
    console.log(`[WEBSOCKET] Client connected from ${clientIp}. Total active clients: ${wsClients.size}`);

    // Immediately transmit live initial market & trading state snapshot
    try {
      ws.send(
        JSON.stringify({
          type: 'init',
          data: {
            prices: symbolPrices,
            activeTrades,
            botStatus,
            accountBalance,
            auditLogs: getRecentAuditLogs(25),
          },
          timestamp: Date.now(),
        })
      );
    } catch (err) {
      console.warn('[WS INIT SNAPSHOT NOTICE]', err);
    }

    ws.on('message', (message) => {
      try {
        const parsed = JSON.parse(message.toString());
        if (parsed.type === 'ping') {
          ws.send(JSON.stringify({ type: 'pong', timestamp: Date.now() }));
        }
      } catch {
        // Non-fatal parse handling
      }
    });

    ws.on('close', () => {
      wsClients.delete(ws);
      console.log(`[WEBSOCKET] Client disconnected. Remaining: ${wsClients.size}`);
    });

    ws.on('error', (err) => {
      console.warn('[WEBSOCKET CLIENT ERROR]', err);
      wsClients.delete(ws);
    });
  });

  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: {
        middlewareMode: true,
        hmr: false,
      },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  await reconcileLivePositionsOnStartup();

  server.listen(PORT, '0.0.0.0', () => {
    console.log(`NovaQuant AI Trading Engine running on http://0.0.0.0:${PORT} (REST & WebSocket /ws active)`);
  });
}

startServer();
